#!/usr/bin/env python3
import sys, json, re
msgs = json.load(sys.stdin)
vals = []
for m in msgs:
    mt = re.search(r'RSS:\s*(\d+)\s*MB', m or '')
    if mt:
        vals.append(int(mt.group(1)))
if vals:
    out = {"count": len(vals), "latest": vals[0], "min": min(vals), "max": max(vals), "avg": round(sum(vals)/len(vals))}
else:
    out = {"count": 0, "latest": 0, "min": 0, "max": 0, "avg": 0}
print(json.dumps(out))
